import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { isAuthenticated, getDashboardRoute, getUser } from '../../utils/auth';

const LandingPage = () => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isScrolled, setIsScrolled] = useState(false);

  // Check if user is already authenticated
  const user = isAuthenticated() ? getUser() : null;
  const dashboardLink = user ? getDashboardRoute(user.role) : '/login';

  const features = [
    {
      icon: '🏢',
      title: 'Room Booking',
      description: 'Pesan ruangan meeting dengan mudah dan cepat',
      color: 'from-blue-500 to-cyan-500'
    },
    {
      icon: '💻',
      title: 'Zoom Integration',
      description: 'Otomatis setup meeting zoom untuk keperluan virtual',
      color: 'from-purple-500 to-indigo-500'
    },
    {
      icon: '⚡',
      title: 'Fast Approval',
      description: 'Sistem approval yang cepat dan transparan',
      color: 'from-green-500 to-emerald-500'
    },
    {
      icon: '📊',
      title: 'Smart Dashboard',
      description: 'Dashboard yang informatif untuk monitoring',
      color: 'from-orange-500 to-red-500'
    }
  ];

  const testimonials = [
    {
      name: 'Ahmad Wijaya',
      role: 'Manager IT',
      avatar: 'AW',
      comment: 'BRIRoom sangat memudahkan proses booking ruangan dan zoom meeting. Interface yang user-friendly!',
      rating: 5
    },
    {
      name: 'Sarah Putri',
      role: 'HR Manager',
      avatar: 'SP',
      comment: 'Sistem approval yang cepat dan transparan. Tim logistik jadi lebih efisien dalam mengelola ruangan.',
      rating: 5
    },
    {
      name: 'Budi Santoso',
      role: 'Project Manager',
      avatar: 'BS',
      comment: 'Tidak perlu lagi repot koordinasi manual. Semua bisa dilakukan melalui satu platform terintegrasi.',
      rating: 5
    }
  ];

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % testimonials.length);
    }, 5000);

    return () => clearInterval(timer);
  }, [testimonials.length]);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (id) => {
    document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <div className="min-h-screen" style={{ background: 'linear-gradient(135deg, #f8fafc 0%, #ffffff 50%, #e0f2fe 100%)' }}>
      {/* Navigation Header */}
      <nav 
        className={`navbar navbar-expand-lg fixed-top transition-all duration-300 ${
          isScrolled 
            ? 'bg-white shadow-lg border-bottom' 
            : 'bg-transparent'
        }`}
        style={{ 
          backdropFilter: isScrolled ? 'blur(10px)' : 'none',
          backgroundColor: isScrolled ? 'rgba(255, 255, 255, 0.9)' : 'transparent'
        }}
      >
        <div className="container">
          {/* Logo */}
          <Link className="navbar-brand d-flex align-items-center" to="/">
            <div 
              className="me-3 d-flex align-items-center justify-content-center"
              style={{
                width: '40px',
                height: '40px',
                background: 'linear-gradient(135deg, #3b82f6 0%, #6366f1 100%)',
                borderRadius: '12px',
                boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)'
              }}
            >
              <span className="text-white fw-bold">B</span>
            </div>
            <div>
              <h1 className="mb-0 fs-5 fw-bold" style={{ 
                background: 'linear-gradient(135deg, #3b82f6 0%, #6366f1 100%)',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent'
              }}>
                BRIRoom
              </h1>
              <small className="text-muted">Meeting Solutions</small>
            </div>
          </Link>

          {/* Navigation Menu */}
          <div className="navbar-nav ms-auto d-none d-md-flex">
            <button 
              onClick={() => scrollToSection('features')}
              className="nav-link btn btn-link text-decoration-none me-3"
            >
              Features
            </button>
            <button 
              onClick={() => scrollToSection('about')}
              className="nav-link btn btn-link text-decoration-none me-3"
            >
              About
            </button>
            <button 
              onClick={() => scrollToSection('testimonials')}
              className="nav-link btn btn-link text-decoration-none me-3"
            >
              Testimonials
            </button>
            <Link
              to={dashboardLink}
              className="btn btn-primary px-4 py-2 rounded-3"
              style={{
                background: 'linear-gradient(135deg, #3b82f6 0%, #6366f1 100%)',
                border: 'none',
                boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)'
              }}
            >
              {user ? 'Dashboard' : 'Login'}
            </Link>
          </div>

          {/* Mobile Menu Button */}
          <div className="d-md-none">
            <Link
              to={dashboardLink}
              className="btn btn-primary btn-sm"
              style={{
                background: 'linear-gradient(135deg, #3b82f6 0%, #6366f1 100%)',
                border: 'none'
              }}
            >
              {user ? 'Dashboard' : 'Login'}
            </Link>
          </div>
        </div>
      </nav>

      {/* Hero Section */}
      <section className="pt-5 pb-5" style={{ paddingTop: '8rem !important', paddingBottom: '6rem !important' }}>
        <div className="container">
          <div className="row align-items-center g-5">
            {/* Content */}
            <div className="col-lg-6">
              <div className="mb-4">
                <span 
                  className="badge px-3 py-2 mb-3"
                  style={{ 
                    backgroundColor: 'rgba(59, 130, 246, 0.1)',
                    color: '#3b82f6',
                    borderRadius: '25px'
                  }}
                >
                  🚀 Welcome to BRIRoom
                </span>
                <h1 className="display-4 fw-bold mb-4 lh-1">
                  Smart Meeting
                  <span 
                    className="d-block"
                    style={{ 
                      background: 'linear-gradient(135deg, #3b82f6 0%, #8b5cf6 50%, #6366f1 100%)',
                      WebkitBackgroundClip: 'text',
                      WebkitTextFillColor: 'transparent'
                    }}
                  >
                    Management
                  </span>
                  <span className="d-block">System</span>
                </h1>
                <p className="fs-5 text-muted mb-4 lh-lg">
                  Solusi terpadu untuk booking ruangan dan zoom meeting. Kelola semua kebutuhan meeting Anda dengan mudah, cepat, dan efisien.
                </p>
              </div>

              <div className="d-flex flex-column flex-sm-row gap-3 mb-5">
                <Link
                  to={dashboardLink}
                  className="btn btn-primary btn-lg px-4 py-3 rounded-4"
                  style={{
                    background: 'linear-gradient(135deg, #3b82f6 0%, #6366f1 100%)',
                    border: 'none',
                    boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)'
                  }}
                >
                  <i className="bi bi-arrow-right me-2"></i>
                  {user ? 'Go to Dashboard' : 'Get Started'}
                </Link>
                <button 
                  onClick={() => scrollToSection('features')}
                  className="btn btn-outline-primary btn-lg px-4 py-3 rounded-4"
                >
                  <i className="bi bi-info-circle me-2"></i>
                  Learn More
                </button>
              </div>

              {/* Stats */}
              <div className="row g-4">
                <div className="col-4 text-center">
                  <div className="h3 fw-bold text-primary mb-1">50+</div>
                  <small className="text-muted">Ruangan</small>
                </div>
                <div className="col-4 text-center">
                  <div className="h3 fw-bold text-primary mb-1">100+</div>
                  <small className="text-muted">Users</small>
                </div>
                <div className="col-4 text-center">
                  <div className="h3 fw-bold text-primary mb-1">24/7</div>
                  <small className="text-muted">Available</small>
                </div>
              </div>
            </div>

            {/* Illustration */}
            <div className="col-lg-6">
              <div className="position-relative">
                {/* Main illustration container */}
                <div 
                  className="rounded-4 p-4 shadow-lg"
                  style={{
                    background: 'linear-gradient(135deg, #3b82f6 0%, #8b5cf6 50%, #6366f1 100%)',
                    transform: 'rotate(3deg)',
                    transition: 'transform 0.5s ease'
                  }}
                  onMouseEnter={(e) => e.target.style.transform = 'rotate(0deg)'}
                  onMouseLeave={(e) => e.target.style.transform = 'rotate(3deg)'}
                >
                  <div 
                    className="bg-white bg-opacity-20 rounded-3 p-4"
                    style={{ backdropFilter: 'blur(10px)' }}
                  >
                    <div className="d-flex justify-content-between align-items-center mb-3">
                      <div 
                        className="bg-white bg-opacity-30 rounded-2"
                        style={{ width: '32px', height: '32px' }}
                      ></div>
                      <div 
                        className="bg-white bg-opacity-30 rounded-pill"
                        style={{ width: '64px', height: '12px' }}
                      ></div>
                    </div>
                    <div className="mb-3">
                      <div 
                        className="bg-white bg-opacity-30 rounded-2 mb-2"
                        style={{ width: '100%', height: '16px' }}
                      ></div>
                      <div 
                        className="bg-white bg-opacity-20 rounded-2 mb-2"
                        style={{ width: '75%', height: '16px' }}
                      ></div>
                      <div 
                        className="bg-white bg-opacity-20 rounded-2"
                        style={{ width: '50%', height: '16px' }}
                      ></div>
                    </div>
                    <div className="row g-2">
                      <div className="col-6">
                        <div 
                          className="bg-white bg-opacity-20 rounded-3"
                          style={{ height: '64px' }}
                        ></div>
                      </div>
                      <div className="col-6">
                        <div 
                          className="bg-white bg-opacity-20 rounded-3"
                          style={{ height: '64px' }}
                        ></div>
                      </div>
                    </div>
                  </div>
                </div>

                {/* Floating elements */}
                <div 
                  className="position-absolute bg-warning rounded-3 d-flex align-items-center justify-content-center shadow"
                  style={{ 
                    top: '-16px',
                    right: '-16px',
                    width: '64px',
                    height: '64px',
                    animation: 'bounce 2s infinite'
                  }}
                >
                  <span style={{ fontSize: '24px' }}>🎯</span>
                </div>
                <div 
                  className="position-absolute bg-success rounded-3 d-flex align-items-center justify-content-center shadow"
                  style={{ 
                    bottom: '-16px',
                    left: '-16px',
                    width: '48px',
                    height: '48px',
                    animation: 'pulse 2s infinite'
                  }}
                >
                  <span style={{ fontSize: '20px' }}>✨</span>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Features Section */}
      <section id="features" className="py-5 bg-white">
        <div className="container">
          <div className="text-center mb-5">
            <span 
              className="badge px-3 py-2 mb-3"
              style={{ 
                backgroundColor: 'rgba(59, 130, 246, 0.1)',
                color: '#3b82f6',
                borderRadius: '25px'
              }}
            >
              ⚡ Key Features
            </span>
            <h2 className="display-5 fw-bold mb-4">
              Mengapa Memilih <span className="text-primary">BRIRoom?</span>
            </h2>
            <p className="fs-5 text-muted mx-auto" style={{ maxWidth: '600px' }}>
              Platform terintegrasi dengan fitur-fitur canggih untuk memenuhi semua kebutuhan meeting Anda
            </p>
          </div>

          <div className="row g-4">
            {features.map((feature, index) => (
              <div key={index} className="col-lg-3 col-md-6">
                <div 
                  className="card h-100 border-0 shadow-sm"
                  style={{ 
                    transition: 'all 0.3s ease',
                    cursor: 'pointer'
                  }}
                  onMouseEnter={(e) => {
                    e.target.style.transform = 'translateY(-8px)';
                    e.target.style.boxShadow = '0 20px 25px -5px rgba(0, 0, 0, 0.1)';
                  }}
                  onMouseLeave={(e) => {
                    e.target.style.transform = 'translateY(0)';
                    e.target.style.boxShadow = '0 1px 3px 0 rgba(0, 0, 0, 0.1)';
                  }}
                >
                  <div className="card-body p-4">
                    <div 
                      className="d-flex align-items-center justify-content-center mb-4 rounded-3 shadow-sm"
                      style={{
                        width: '64px',
                        height: '64px',
                        background: `linear-gradient(135deg, ${feature.color.split(' ')[1]} 0%, ${feature.color.split(' ')[3]} 100%)`
                      }}
                    >
                      <span style={{ fontSize: '24px' }}>{feature.icon}</span>
                    </div>
                    <h5 className="card-title fw-bold mb-3">{feature.title}</h5>
                    <p className="card-text text-muted">{feature.description}</p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* About Section */}
      <section id="about" className="py-5" style={{ backgroundColor: '#f8fafc' }}>
        <div className="container">
          <div className="row align-items-center g-5">
            <div className="col-lg-6">
              <span 
                className="badge px-3 py-2 mb-3"
                style={{ 
                  backgroundColor: 'rgba(59, 130, 246, 0.1)',
                  color: '#3b82f6',
                  borderRadius: '25px'
                }}
              >
                🏢 About BRIRoom
              </span>
              <h2 className="display-5 fw-bold mb-4">
                Solusi Terdepan untuk 
                <span className="d-block text-primary">Meeting Management</span>
              </h2>
              <p className="fs-5 text-muted mb-4">
                BRIRoom adalah platform inovatif yang dirancang khusus untuk memudahkan pengelolaan ruangan meeting dan integrasi zoom di lingkungan BRI. Dengan teknologi terdepan dan user experience yang intuitif.
              </p>

              <div className="row g-4">
                <div className="col-12">
                  <div className="d-flex">
                    <div 
                      className="flex-shrink-0 me-3 d-flex align-items-center justify-content-center bg-success bg-opacity-10 rounded-3"
                      style={{ width: '48px', height: '48px' }}
                    >
                      <i className="bi bi-check-lg text-success fs-5"></i>
                    </div>
                    <div>
                      <h5 className="fw-bold mb-2">Sistem Terintegrasi</h5>
                      <p className="text-muted mb-0">Satu platform untuk semua kebutuhan meeting, dari booking ruangan hingga setup zoom otomatis.</p>
                    </div>
                  </div>
                </div>
                <div className="col-12">
                  <div className="d-flex">
                    <div 
                      className="flex-shrink-0 me-3 d-flex align-items-center justify-content-center bg-primary bg-opacity-10 rounded-3"
                      style={{ width: '48px', height: '48px' }}
                    >
                      <i className="bi bi-lightning-fill text-primary fs-5"></i>
                    </div>
                    <div>
                      <h5 className="fw-bold mb-2">Proses Cepat</h5>
                      <p className="text-muted mb-0">Approval otomatis dengan workflow yang efisien, mengurangi waktu tunggu approval manual.</p>
                    </div>
                  </div>
                </div>
                <div className="col-12">
                  <div className="d-flex">
                    <div 
                      className="flex-shrink-0 me-3 d-flex align-items-center justify-content-center bg-info bg-opacity-10 rounded-3"
                      style={{ width: '48px', height: '48px' }}
                    >
                      <i className="bi bi-person-check-fill text-info fs-5"></i>
                    </div>
                    <div>
                      <h5 className="fw-bold mb-2">User Friendly</h5>
                      <p className="text-muted mb-0">Interface yang intuitif dan mudah digunakan untuk semua kalangan, dari staff hingga management.</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            <div className="col-lg-6">
              <div 
                className="rounded-4 p-4 shadow-lg"
                style={{
                  background: 'linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%)'
                }}
              >
                <div className="bg-white rounded-3 p-4">
                  <div className="d-flex justify-content-between align-items-center mb-3">
                    <h6 className="fw-bold mb-0">Meeting Dashboard</h6>
                    <div 
                      className="bg-success rounded-circle"
                      style={{ width: '12px', height: '12px' }}
                    ></div>
                  </div>
                  <div className="row g-2">
                    <div className="col-12">
                      <div className="bg-primary bg-opacity-10 rounded-2 p-3">
                        <div className="d-flex justify-content-between align-items-center">
                          <span className="fw-medium">Room A - 09:00</span>
                          <span className="badge bg-success">Approved</span>
                        </div>
                      </div>
                    </div>
                    <div className="col-12">
                      <div className="bg-info bg-opacity-10 rounded-2 p-3">
                        <div className="d-flex justify-content-between align-items-center">
                          <span className="fw-medium">Zoom Meeting - 14:00</span>
                          <span className="badge bg-info">Active</span>
                        </div>
                      </div>
                    </div>
                    <div className="col-12">
                      <div className="bg-warning bg-opacity-10 rounded-2 p-3">
                        <div className="d-flex justify-content-between align-items-center">
                          <span className="fw-medium">Both - 16:00</span>
                          <span className="badge bg-warning">Pending</span>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Testimonials Section */}
      <section id="testimonials" className="py-5 bg-white">
        <div className="container">
          <div className="text-center mb-5">
            <span 
              className="badge px-3 py-2 mb-3"
              style={{ 
                backgroundColor: 'rgba(139, 92, 246, 0.1)',
                color: '#8b5cf6',
                borderRadius: '25px'
              }}
            >
              💬 Testimonials
            </span>
            <h2 className="display-5 fw-bold mb-4">
              Apa Kata <span style={{ color: '#8b5cf6' }}>Pengguna?</span>
            </h2>
            <p className="fs-5 text-muted mx-auto" style={{ maxWidth: '600px' }}>
              Dengar langsung dari pengguna yang telah merasakan kemudahan BRIRoom
            </p>
          </div>

          <div className="row justify-content-center">
            <div className="col-lg-8">
              <div 
                className="card border-0 shadow-lg rounded-4 p-4"
                style={{ background: 'linear-gradient(135deg, #f3e8ff 0%, #ddd6fe 100%)' }}
              >
                <div className="card-body text-center p-4">
                  {/* Avatar */}
                  <div 
                    className="d-flex align-items-center justify-content-center mx-auto mb-4 shadow-sm"
                    style={{
                      width: '80px',
                      height: '80px',
                      background: 'linear-gradient(135deg, #8b5cf6 0%, #3b82f6 100%)',
                      borderRadius: '50%'
                    }}
                  >
                    <span className="text-white fw-bold fs-4">
                      {testimonials[currentSlide].avatar}
                    </span>
                  </div>

                  {/* Stars */}
                  <div className="mb-4">
                    {[...Array(testimonials[currentSlide].rating)].map((_, i) => (
                      <i key={i} className="bi bi-star-fill text-warning me-1"></i>
                    ))}
                  </div>

                  {/* Quote */}
                  <blockquote className="fs-5 fw-medium fst-italic mb-4 lh-lg">
                    "{testimonials[currentSlide].comment}"
                  </blockquote>

                  {/* Author */}
                  <div>
                    <div className="fw-bold fs-5 mb-1">
                      {testimonials[currentSlide].name}
                    </div>
                    <div className="text-muted">
                      {testimonials[currentSlide].role}
                    </div>
                  </div>
                </div>
              </div>

              {/* Navigation dots */}
              <div className="d-flex justify-content-center mt-4">
                {testimonials.map((_, index) => (
                  <button
                    key={index}
                    onClick={() => setCurrentSlide(index)}
                    className={`btn btn-sm mx-1 ${
                      index === currentSlide ? 'btn-primary' : 'btn-outline-secondary'
                    }`}
                    style={{
                      width: index === currentSlide ? '32px' : '12px',
                      height: '12px',
                      borderRadius: '6px',
                      transition: 'all 0.3s ease'
                    }}
                  />
                ))}
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section 
        className="py-5 text-white text-center"
        style={{ background: 'linear-gradient(135deg, #3b82f6 0%, #8b5cf6 50%, #6366f1 100%)' }}
      >
        <div className="container">
          <div className="row justify-content-center">
            <div className="col-lg-8">
              <h2 className="display-5 fw-bold mb-4">
                Siap Untuk Memulai?
              </h2>
              <p className="fs-5 mb-5 opacity-75">
                Bergabunglah dengan BRIRoom dan rasakan kemudahan mengelola meeting Anda. 
                Dapatkan akses ke platform yang akan mengubah cara Anda bekerja.
              </p>

              <Link
                to={dashboardLink}
                className="btn btn-light btn-lg px-5 py-3 rounded-4 fw-bold"
                style={{ boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)' }}
              >
                <i className="bi bi-arrow-right me-2"></i>
                {user ? 'Go to Dashboard' : 'Login Sekarang'}
              </Link>
            </div>
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="bg-dark text-white py-5">
        <div className="container">
          <div className="row g-4">
            {/* Brand */}
            <div className="col-lg-6">
              <div className="d-flex align-items-center mb-3">
                <div 
                  className="me-3 d-flex align-items-center justify-content-center"
                  style={{
                    width: '40px',
                    height: '40px',
                    background: 'linear-gradient(135deg, #3b82f6 0%, #6366f1 100%)',
                    borderRadius: '12px'
                  }}
                >
                  <span className="text-white fw-bold">B</span>
                </div>
                <div>
                  <h5 className="mb-0 text-white">BRIRoom</h5>
                  <small className="text-muted">Meeting Solutions</small>
                </div>
              </div>
              <p className="text-muted mb-3" style={{ maxWidth: '400px' }}>
                Platform terpadu untuk mengelola ruangan meeting dan zoom dengan mudah, cepat, dan efisien di lingkungan BRI.
              </p>
              <small className="text-muted">
                © 2025 BRIRoom. All rights reserved.
              </small>
            </div>

            {/* Quick Links */}
            <div className="col-lg-3">
              <h6 className="fw-bold text-white mb-3">Quick Links</h6>
              <div className="d-flex flex-column">
                <button 
                  onClick={() => scrollToSection('features')} 
                  className="btn btn-link text-muted text-start p-0 mb-2 text-decoration-none"
                >
                  Features
                </button>
                <button 
                  onClick={() => scrollToSection('about')} 
                  className="btn btn-link text-muted text-start p-0 mb-2 text-decoration-none"
                >
                  About
                </button>
                <button 
                  onClick={() => scrollToSection('testimonials')} 
                  className="btn btn-link text-muted text-start p-0 mb-2 text-decoration-none"
                >
                  Testimonials
                </button>
              </div>
            </div>

            {/* Contact */}
            <div className="col-lg-3">
              <h6 className="fw-bold text-white mb-3">Contact</h6>
              <div className="d-flex align-items-center mb-2">
                <i className="bi bi-envelope me-2 text-muted"></i>
                <small className="text-muted">support@briroom.com</small>
              </div>
              <div className="d-flex align-items-center">
                <i className="bi bi-telephone me-2 text-muted"></i>
                <small className="text-muted">+62 21 1500 017</small>
              </div>
            </div>
          </div>
        </div>
      </footer>

      {/* Custom CSS for animations */}
      <style jsx>{`
        @keyframes bounce {
          0%, 20%, 53%, 80%, 100% {
            transform: translate3d(0,0,0);
          }
          40%, 43% {
            transform: translate3d(0,-8px,0);
          }
          70% {
            transform: translate3d(0,-4px,0);
          }
          90% {
            transform: translate3d(0,-2px,0);
          }
        }

        @keyframes pulse {
          0% {
            transform: scale(1);
          }
          50% {
            transform: scale(1.1);
          }
          100% {
            transform: scale(1);
          }
        }

        html {
          scroll-behavior: smooth;
        }
      `}</style>
    </div>
  );
};

export default LandingPage;
